$products = [[1, 'Áo thun basic cotton cổ tròn', 'ao-thun-basic-cotton-co-tron', 189000, 149000, '<p>Áo thun cotton 100% 250gsm thoáng mát, form regular fit dễ phối đồ unisex.</p>', 1, 1, 547], [2, 'Áo thun oversize form rộng', 'ao-thun-oversize-form-rong', 229000, 179000, '<p>Áo thun form oversize thụng vai cá tính đậm chất streetwear đường phố.</p>', 1, 1, 594], [3, 'Áo thun in hình graphic', 'ao-thun-in-hinh-graphic', 249000, 199000, '<p>Họa tiết in lụa graphic nổi bật, sắc nét, không bong tróc khi giặt máy.</p>', 1, 1, 641], [4, 'Áo thun tay dài thu đông', 'ao-thun-tay-dai-thu-dong', 259000, null, '<p>Áo thun tay dài chất vải cotton dày dặn, giữ ấm nhẹ nhàng cho tiết trời thu đông.</p>', 1, 1, 688], [5, 'Áo croptop nữ ôm body', 'ao-croptop-nu-om-body', 179000, 139000, '<p>Áo croptop ôm dáng tôn vòng eo thon gọn, chất thun gân co giãn 4 chiều.</p>', 1, 1, 735], [6, 'Áo polo cổ bẻ thể thao', 'ao-polo-co-be-the-thao', 279000, 229000, '<p>Áo polo thể thao chất cá sấu mắt chim thoáng khí, bo cổ dệt kim cao cấp.</p>', 2, 1, 782], [7, 'Áo polo trơn basic', 'ao-polo-tron-basic', 259000, null, '<p>Thiết kế cổ bẻ trơn thanh lịch, thích hợp cả đi học, đi làm và dạo phố.</p>', 2, 1, 829], [8, 'Áo sơ mi trắng công sở', 'ao-so-mi-trang-cong-so', 289000, 239000, '<p>Áo sơ mi vải lụa tuyết chống nhăn, form đứng chuẩn mực lịch thiệp.</p>', 2, 1, 876], [9, 'Áo sơ mi kẻ sọc', 'ao-so-mi-ke-soc', 299000, 249000, '<p>Họa tiết kẻ sọc thanh mảnh kéo dài dáng người, phong cách smart casual hiện đại.</p>', 2, 1, 923], [10, 'Áo sơ mi linen nữ tay dài', 'ao-so-mi-linen-nu-tay-dai', 319000, 269000, '<p>Chất liệu linen tự nhiên mềm rũ thoáng khí, tông màu pastel dịu dàng nữ tính.</p>', 2, 1, 970], [11, 'Áo sơ mi flannel caro', 'ao-so-mi-flannel-caro', 329000, null, '<p>Chất vải flannel dạ mềm ấm, phối caro vintage đậm chất đường phố Mỹ.</p>', 2, 1, 1017], [12, 'Áo khoác denim jean unisex', 'ao-khoac-denim-jean-unisex', 429000, 369000, '<p>Denim wash cao cấp dày dặn, nút kim loại khắc chìm chống gỉ bền bỉ theo năm tháng.</p>', 5, 1, 1064], [13, 'Áo khoác varsity bóng chày', 'ao-khoac-varsity-bong-chay', 469000, 399000, '<p>Form varsity bóng chày bo gân kẻ sọc thể thao, lớp lót dù cách nhiệt cản gió tốt.</p>', 5, 1, 1111], [14, 'Áo bomber dù thể thao', 'ao-bomber-du-the-thao', 399000, 349000, '<p>Vải dù 2 lớp chống thấm nước nhẹ, cản gió giữ ấm hiệu quả cho ngày se lạnh.</p>', 5, 1, 1158], [15, 'Áo hoodie nỉ bông form rộng', 'ao-hoodie-ni-bong-form-rong', 379000, 319000, '<p>Nỉ bông trần bông dày dặn ấm áp, mũ trùm 2 lớp có dây rút tiện dụng.</p>', 5, 1, 1205], [16, 'Áo hoodie zip khóa kéo', 'ao-hoodie-zip-khoa-keo', 389000, null, '<p>Khóa kéo kim loại trơn tru, túi kangaroo tiện lợi đựng điện thoại và giữ ấm tay.</p>', 5, 1, 1252], [17, 'Quần jeans straight fit', 'quan-jeans-straight-fit', 389000, 329000, '<p>Ống đứng straight tôn dáng chân dài, vải denim cotton dày có độ co giãn 2% thoải mái.</p>', 3, 1, 1299], [18, 'Quần jean ống rộng nữ', 'quan-jean-ong-rong-nu', 369000, 319000, '<p>Cạp cao che khuyết điểm bụng, ống rộng che bắp chân cực đỉnh cho phái nữ.</p>', 3, 1, 1346], [19, 'Quần jean rách gối', 'quan-jean-rach-goi', 399000, 339000, '<p>Chi tiết rách gối mài xước thủ công phong cách bụi bặm, phá cách cho bạn trẻ.</p>', 3, 1, 1393], [20, 'Quần jean baggy', 'quan-jean-baggy', 359000, null, '<p>Dáng baggy đùi rộng gấu ôm nhẹ, dễ mặc phù hợp với mọi vóc dáng.</p>', 3, 1, 1440], [21, 'Quần short jean nam', 'quan-short-jean-nam', 279000, 229000, '<p>Quần lửng jean ngang gối năng động, chất denim co giãn nhẹ cho mùa hè mát mẻ.</p>', 3, 1, 1487], [22, 'Quần short thể thao', 'quan-short-the-thao', 219000, 169000, '<p>Chất dù polyeste thể thao nhẹ tênh, cạp chun có dây rút co giãn tối đa.</p>', 3, 1, 1534], [23, 'Quần short nữ', 'quan-short-nu', 229000, 189000, '<p>Short nữ lưng cao tôn dáng chân, chất kaki mềm mịn thoáng mát.</p>', 3, 1, 1581], [24, 'Quần kaki', 'quan-kaki', 349000, 299000, '<p>Quần dài kaki cotton chống nhăn, phom dáng slimfit vừa vặn chỉn chu.</p>', 3, 1, 1628], [25, 'Quần tây ống rộng', 'quan-tay-ong-rong', 359000, null, '<p>Quần âu ống suông rộng xếp ly chuẩn Hàn Quốc, chất vải tuyết mưa mềm rũ thanh lịch.</p>', 3, 1, 1675], [26, 'Váy midi hoa nhí', 'vay-midi-hoa-nhi', 389000, 329000, '<p>Họa tiết hoa nhí nữ tính trên nền voan cát mềm mại, dáng váy xòe bồng bềnh thanh lịch.</p>', 4, 1, 1722], [27, 'Váy midi dáng dài', 'vay-midi-dang-dai', 369000, null, '<p>Dáng váy midi qua gối kín đáo, xếp ly nhẹ nhàng thướt tha trong từng bước chân.</p>', 4, 1, 1769], [28, 'Đầm maxi dự tiệc', 'dam-maxi-du-tiec', 549000, 459000, '<p>Đầm maxi hai dây dáng dài quyến rũ, chất lụa satin bóng nhẹ sang trọng cho buổi tiệc đêm.</p>', 4, 1, 1816], [29, 'Chân váy chữ A', 'chan-vay-chu-a', 279000, 229000, '<p>Chân váy dáng chữ A tôn eo giấu hông cực tốt, cạp cao lưng êm mặc cả ngày dễ chịu.</p>', 4, 1, 1863], [30, 'Chân váy xếp ly', 'chan-vay-xep-ly', 329000, 279000, '<p>Xếp ly dập nhiệt công nghệ cao chống bung nếp, phong cách tennis skirt trẻ trung năng động.</p>', 4, 1, 1910]];
